  p.steps.forEach(s=>{const a=DATA.assistants[`${p.slug}/${s.id}`];a.questions.forEach(q=>{q.refs.forEach(r=>ids.add(r));q.criteria.forEach(c=>c.refs.forEach(r=>ids.add(r)));});a.rules.forEach(r=>r.refs.forEach(id=>ids.add(id)));});
  return [...ids];
};

